(4, 0, 0, 'call-back-form', '', 0, 1, 0, '<!-- Ð·Ð°ÐºÐ°Ð· Ð¾Ð±Ñ€Ð°Ñ‚Ð½Ð¾Ð³Ð¾ Ð·Ð²Ð¾Ð½ÐºÐ° -->\n<div class="cb-wrapper">\n    <span class="cb-trigger">Ð—Ð°ÐºÐ°Ð·Ð°Ñ‚ÑŒ Ð¾Ð±Ñ€Ð°Ñ‚Ð½Ñ‹Ð¹ Ð·Ð²Ð¾Ð½Ð¾Ðº</span>\n    <div class="cb-slide-helper">\n        <div class="cb-form">\n            <div class="cb-header">Ð—Ð°ÐºÐ°Ð·Ð°Ñ‚ÑŒ Ð¾Ð±Ñ€Ð°Ñ‚Ð½Ñ‹Ð¹ Ð·Ð²Ð¾Ð½Ð¾Ðº<i class="cb-close fa fa-times"></i></div>\n            <table>\n                <tbody>\n                    <tr>\n                        <td><i class="fa fa-user"></i></td>\n                        <td><input type="text" name="name" class="cb-input" placeholder="Ð˜Ð¼Ñ"></td>\n                    </tr>\n                    <tr>\n                        <td><i class="fa fa-phone-square"></i></td>\n                        <td><input type="text" name="tel" class="cb-input" placeholder="Ð¢ÐµÐ»ÐµÑ„Ð¾Ð½"></td>\n                    </tr>\n                    <tr>\n                        <td><i class="fa fa-clock-o"></i></td>\n                        <td>\n                            <select name="cb-time">\n        						<option value="ÐŸÑ€ÐµÐ´Ð¿Ð¾Ñ‡Ñ‚Ð¸Ñ‚ÐµÐ»ÑŒÐ½Ð¾Ðµ Ð²Ñ€ÐµÐ¼Ñ Ð·Ð²Ð¾Ð½Ð° Ð½Ðµ Ð²Ñ‹Ð±Ñ€Ð°Ð½Ð¾">Ð’Ñ‹Ð±Ñ€Ð°Ñ‚ÑŒ Ð²Ñ€ÐµÐ¼Ñ</option>\n        						<option value="ÐŸÐµÑ€ÐµÐ·Ð²Ð¾Ð½Ð¸Ñ‚ÑŒ Ñ 09:00 Ð´Ð¾ 10:00">Ñ 09:00 Ð´Ð¾ 10:00</option>\n        						<option value="ÐŸÐµÑ€ÐµÐ·Ð²Ð¾Ð½Ð¸Ñ‚ÑŒ Ñ 10:00 Ð´Ð¾ 11:00">Ñ 10:00 Ð´Ð¾ 11:00</option>\n        						<option value="ÐŸÐµÑ€ÐµÐ·Ð²Ð¾Ð½Ð¸Ñ‚ÑŒ Ñ 11:00 Ð´Ð¾ 12:00">Ñ 11:00 Ð´Ð¾ 12:00</option>\n        						<option value="ÐŸÐµÑ€ÐµÐ·Ð²Ð¾Ð½Ð¸Ñ‚ÑŒ Ñ 12:00 Ð´Ð¾ 13:00">Ñ 12:00 Ð´Ð¾ 13:00</option>\n        						<option value="ÐŸÐµÑ€ÐµÐ·Ð²Ð¾Ð½Ð¸Ñ‚ÑŒ Ñ 13:00 Ð´Ð¾ 14:00">Ñ 13:00 Ð´Ð¾ 14:00</option>\n        						<option value="ÐŸÐµÑ€ÐµÐ·Ð²Ð¾Ð½Ð¸Ñ‚ÑŒ Ñ 14:00 Ð´Ð¾ 15:00">Ñ 14:00 Ð´Ð¾ 15:00</option>\n        						<option value="ÐŸÐµÑ€ÐµÐ·Ð²Ð¾Ð½Ð¸Ñ‚ÑŒ Ñ 15:00 Ð´Ð¾ 16:00">Ñ 15:00 Ð´Ð¾ 16:00</option>\n        						<option value="ÐŸÐµÑ€ÐµÐ·Ð²Ð¾Ð½Ð¸Ñ‚ÑŒ Ñ 16:00 Ð´Ð¾ 17:00">Ñ 16:00 Ð´Ð¾ 17:00</option>\n        						<option value="ÐŸÐµÑ€ÐµÐ·Ð²Ð¾Ð½Ð¸Ñ‚ÑŒ Ñ 17:00 Ð´Ð¾ 18:00">Ñ 17:00 Ð´Ð¾ 18:00</option>\n        						<option value="ÐŸÐµÑ€ÐµÐ·Ð²Ð¾Ð½Ð¸Ñ‚ÑŒ Ñ 18:00 Ð´Ð¾ 19:00">Ñ 18:00 Ð´Ð¾ 19:00</option>\n        						<option value="ÐŸÐµÑ€ÐµÐ·Ð²Ð¾Ð½Ð¸Ñ‚ÑŒ Ñ 19:00 Ð´Ð¾ 20:00">Ñ 19:00 Ð´Ð¾ 20:00</option>\n        						<option value="ÐŸÐµÑ€ÐµÐ·Ð²Ð¾Ð½Ð¸Ñ‚ÑŒ Ñ 20:00 Ð´Ð¾ 21:00">Ñ 20:00 Ð´Ð¾ 21:00</option>\n                            </select>\n                        </td>\n                    </tr>\n                </tbody>\n            </table>\n            <div class="cb-clear"></div>\n            <div class="cb-go">Ð–Ð´Ñƒ Ð·Ð²Ð¾Ð½ÐºÐ°!</div>\n            <div class="cb-return"></div>\n        </div>\n    </div>\n</div>\n<script type="text/javascript">\n$(document).ready(function(){\n$(document.body).on("click", ".cb-trigger", function(){$(this).parent().find(".cb-slide-helper").slideToggle();});\n$(document.body).on("click", ".cb-close", function(){$(this).parents(".cb-slide-helper").slideToggle();});\n$(document.body).on("click", ".cb-go", $(".cb-form"), cbSend);\n$(document.body).on("focus", ".cb-input", function(){$(this).parent().parent().removeClass("cb-error");});\n\nfunction cbSend(cb){\ncb = cb.data;\nvar tel = cb.find("input[name=''tel'']");\nvar name = cb.find("input[name=''name'']");\nvar time = cb.find("select[name=''cb-time'']");\nvar validate = true;\n\nif (name.val().length < 1){name.parent().parent().addClass("cb-error");validate = false;}\nif (tel.val().length < 1){tel.parent().parent().addClass("cb-error");validate = false;}\nconsole.log("asd");\nif (validate){\nvar need = "";\nneed += "<br>ÐšÐ¾Ð½Ñ‚Ð°ÐºÑ‚Ð½Ð°Ñ Ð¸Ð½Ñ„Ð¾Ñ€Ð¼Ð°Ñ†Ð¸Ñ: Ð˜Ð¼Ñ â€“ <b>" + name.val() + "</b><br>Ð¢ÐµÐ»ÐµÑ„Ð¾Ð½ â€“ <b>" + tel.val() + "</b><br>" + time.val();\n    \noutput = JSON.stringify(need);\n\n$.ajax({\ntype: "POST",\ndata: {data1: output},\n  url:''js/mail.php'',\n  dataType:''json'',\n  success: function(data){\n    $(".cb-return").html(data.result);\n    $(".cb-go").hide();\n    $(".cb-return").fadeIn(300);\n},\nerror: function(data){console.log("Ð¾ÑˆÐ¸Ð±ÐºÐ°");}\n});\n}\n}\n});\n</script>', 0, 'a:0:{}', 0, ''),
(5, 0, 0, 'colorbox-css', '', 0, 1, 0, '<link href="css/colorbox.css" rel="stylesheet">', 0, NULL, 0, ''),
(6, 0, 0, 'colorbox-js', '', 0, 1, 0, '<script src="js/jquery.colorbox-min.js"></script>', 0, 'a:0:{}', 0, ''),
(7, 0, 0, 'css', 'Ð¡Ñ‚Ð¸Ð»Ð¸ Ð´Ð»Ñ Ð²ÑÐµÑ… ÑÐ»ÐµÐ¼ÐµÐ½Ñ‚Ð¾Ð², Ð½Ðµ Ð¸ÑÐ¿Ð¾Ð»ÑŒÐ·ÑƒÑŽÑ‰Ð¸Ñ… Ð¿Ð¾Ð´ÐºÐ»ÑŽÑ‡Ð°ÐµÐ¼Ñ‹Ðµ Ñ„Ð°Ð¹Ð»Ñ‹ .css', 0, 1, 0, '/* Ð—Ð°ÐºÐ°Ð· Ð¾Ð±Ñ€Ð°Ñ‚Ð½Ð¾Ð³Ð¾ Ð·Ð²Ð¾Ð½ÐºÐ° css */\n.cb-wrapper {\nposition: relative;\nwidth:352px;\ntext-align:center;\n}\n.cb-trigger {\nborder-bottom: 1px dashed;\ncursor: pointer;\n}\n.cb-slide-helper {\nposition: absolute;\npadding: 13px;\ntop: -11px;\ndisplay: none;\ntext-align:left;\n}\n.cb-form {\nwidth: 300px;\nposition: relative;\nbackground: #fff;\ntext-align: left;\npadding: 0 55px 15px;\nborder-radius: 12px;\nborder: 2px solid #0076b7;\n}\n.cb-header {\npadding: 13px;\nfont-size: 18px;\ntext-align: center;\n}\n.cb-close {\nposition: absolute;\nwidth: 16px;\nheight: 16px;\ntop: 5px;\nright: 5px;\ncursor: pointer;\ncolor: #000;\nopacity: 0.3;\n}\n.cb-close:hover{\nopacity: 1;\n}\n.cb-form table {\nwidth: 100%;\nmargin-bottom: 10px;\n}\n.cb-form table td:first-child {\nwidth: 25px;\n}\n.cb-form table .fa {\nfont-size: 20px;\nheight: 18px;\npadding: 2px 0;\ncolor: #444;\n}\n.cb-form input, .cb-form select {\nwidth: 100%;\npadding: 3px 5px;\noutline: 0;\nbox-sizing: border-box;\nborder: 1px solid #ccc;\n}\n.fb-form input:focus, .fb-form textarea:focus, .fb-form select:focus {\nborder-color: #66afe9 !important;\noutline: 0;\n-webkit-box-shadow: inset 0 1px 1px rgba(0,0,0,.075),0 0 8px rgba(102,175,233,1);\nbox-shadow: inset 0 1px 1px rgba(0,0,0,.075),0 0 8px rgba(102,175,233,1);\n}\n.cb-clear {\nclear: both;\nwidth: 100%;\nheight: 1px;\nmargin: 0;\n}\n.cb-go {\noutline: none;\nborder: 0;\nmargin: 0 auto;\nwidth: 120px;\nheight: 30px;\ntext-align: center;\nline-height: 30px;\nborder-radius: 4px;\nbackground: #0076b7;\ncolor: #fff;\nborder-bottom: 3px solid #03579E;\ncursor: pointer;\n}\n.cb-go:hover {\nbackground: #0084CC;\nborder-bottom: 3px solid #0064B9;\n}\n.cb-go:active {\nborder-bottom: 0;\nmargin-top: 3px;\n}\n.cb-error .fa{\n    color:#D22;\n}\n.cb-error input{\n    border:1px solid #D22;\n}\n.cb-return {\ntext-align: right;\nfont-size: 0.9em;\nopacity: 0.7;\n}\n/* Ð³ÐµÐ½ÐµÑ€Ð°Ñ‚Ð¾Ñ€ ÑÐ»ÐµÐ¼ÐµÐ½Ñ‚Ð¾Ð² modx */\n.gi-item {\nwidth: 23%;\ntext-align: center;\nmargin: 0 1%;\nfloat: left;\nbox-sizing: border-box;\nmargin-bottom: 15px;\n}\n.gi-image {\ndisplay: block;\n}\n.gi-image img {\n/*height: 130px;*/\npadding: 4px;\nborder: 1px solid transparent;\nborder-radius: 3px;\nwidth: 100%;\nbox-sizing: border-box;\n}\n.gi-item:hover img {\n    border-color:#D8D8D8;\n}\n.gi-name {\ndisplay: block;\ntext-decoration:none;\n}\n.gi-item:hover a {\n    text-decoration:underline;\n}\n/* Ñ„Ð¾Ñ€Ð¼Ð° Ð¾Ð±Ñ€Ð°Ñ‚Ð½Ð¾Ð¹ ÑÐ²ÑÐ·Ð¸ css */\n#fb-wrapper {\nborder: 2px solid #0076b7;\nwidth: 100%;\nmargin-bottom: 4px;\nborder-radius: 15px;\n}\n#fb-form {\nwidth: 700px;\nmargin: 0 auto;\n}\n#fb-form td {\nvertical-align: middle;\n}\n#fb-form input,  #fb-form textarea, #fb-form select {\nwidth: 100%;\npadding:3px;\nborder:1px solid #ccc;\nfont-family:inherit;\noutline:0;\n}\n#fb-header {\npadding: 0;\ntext-align: center;\nmargin: 17px;\n}\n#fb-form td {\nvertical-align: middle;\n}\n#fb-ajaxgo {\noutline: none;\nborder: 0;\nmargin: 0 auto;\nwidth: 120px;\nheight: 33px;\nline-height: 33px;\nborder-radius: 4px;\nbackground: #0076b7;\ncolor: #fff;\nborder-bottom: 3px solid #03579E;\ncursor: pointer;\n}\n#fb-ajaxgo:hover {\nbackground: #0084CC;\nborder-bottom: 3px solid #0064B9;\n}\n#fb-ajaxgo:active {\nborder-bottom: 0;\nmargin-top: 3px;\n}\n#fb-button-wr{\nheight: 38px;padding-top:10px; text-align:center; margin-bottom: 7px;position: relative;\n}\n#fb-successmsg {\ndisplay: none;\nbackground: #fff;\npadding: 5px 15px;\nborder: 1px solid #ccc;\nborder-radius: 7px;\nbottom: 5px;\nright: 10px;\nmargin: 0 auto;\nwidth: 240px;\ncursor:default;\n}\n/* list-item genegator css */\n#sl-list {\nmargin: 15px 0;\npadding: 0;\nlist-style: none;\n}\n#sl-list li {\nmargin-bottom: 7px;\n}\n#sl-list a {\ndisplay: block;\npadding: 7px 15px;\ntext-decoration: none;\nbackground: #0076b7;\nborder-radius: 7px;\ncolor: #fff;\nborder: 1px solid #03579E;\n}\n#sl-list a:hover {\nbackground: #0084CC;\nborder-color: #0064B9;\n}\n/* Ð½Ð¾Ð²Ð¾ÑÑ‚Ð¸ Ð²Ð½ÑƒÑ‚Ñ€ÐµÐ½ÑÑ ÑÑ‚Ñ€Ð°Ð½Ð¸Ñ†Ð° */\n.news-item {\nmargin-bottom: 15px;\n}\n.news-item h3 {\nmargin: 0 0 7px;\nfont-size:18px;\nfont-wieght:bold;\npadding:0;\nline-height:normal;\n}\n.news-item h3 span {\nfloat: right;\nfont-size: 0.8em;\nfont-weight: normal;\n}\n.news-item-short span {\nborder-bottom: 1px dotted;\ncursor: pointer;\n}\n.news-item-content {\ndisplay: none;\npadding: 15px 0 5px;\nborder-bottom: 1px solid #ccc;\n}\n.news-item-content p {\nmargin: 0 0 7px;\n}\n/* ÐÐ½Ð¸Ð¼Ð°Ñ†Ð¸Ñ http://daneden.github.io/animate.css/ */\n.animated {\n  -webkit-animation-duration: 1s;\n          animation-duration: 1s;\n  -webkit-animation-fill-mode: both;\n          animation-fill-mode: both;\n}\n\n.animated.infinite {\n  -webkit-animation-iteration-count: infinite;\n          animation-iteration-count: infinite;\n}\n\n.animated.hinge {\n  -webkit-animation-duration: 2s;\n          animation-duration: 2s;\n}\n\n@-webkit-keyframes shake{0%,100%{-webkit-transform:translate3d(0,0,0);transform:translate3d(0,0,0)}10%,30%,50%,70%,90%{-webkit-transform:translate3d(-10px,0,0);transform:translate3d(-10px,0,0)}20%,40%,60%,80%{-webkit-transform:translate3d(10px,0,0);transform:translate3d(10px,0,0)}}@keyframes shake{0%,100%{-webkit-transform:translate3d(0,0,0);transform:translate3d(0,0,0)}10%,30%,50%,70%,90%{-webkit-transform:translate3d(-10px,0,0);transform:translate3d(-10px,0,0)}20%,40%,60%,80%{-webkit-transform:translate3d(10px,0,0);transform:translate3d(10px,0,0)}}\n\n.shake {-webkit-animation-name: shake;animation-name: shake;}\n\n@-webkit-keyframes tada{0%{-webkit-transform:scale3d(1,1,1);transform:scale3d(1,1,1)}10%,20%{-webkit-transform:scale3d(.9,.9,.9) rotate3d(0,0,1,-3deg);transform:scale3d(.9,.9,.9) rotate3d(0,0,1,-3deg)}30%,50%,70%,90%{-webkit-transform:scale3d(1.1,1.1,1.1) rotate3d(0,0,1,3deg);transform:scale3d(1.1,1.1,1.1) rotate3d(0,0,1,3deg)}40%,60%,80%{-webkit-transform:scale3d(1.1,1.1,1.1) rotate3d(0,0,1,-3deg);transform:scale3d(1.1,1.1,1.1) rotate3d(0,0,1,-3deg)}100%{-webkit-transform:scale3d(1,1,1);transform:scale3d(1,1,1)}}@keyframes tada{0%{-webkit-transform:scale3d(1,1,1);transform:scale3d(1,1,1)}10%,20%{-webkit-transform:scale3d(.9,.9,.9) rotate3d(0,0,1,-3deg);transform:scale3d(.9,.9,.9) rotate3d(0,0,1,-3deg)}30%,50%,70%,90%{-webkit-transform:scale3d(1.1,1.1,1.1) rotate3d(0,0,1,3deg);transform:scale3d(1.1,1.1,1.1) rotate3d(0,0,1,3deg)}40%,60%,80%{-webkit-transform:scale3d(1.1,1.1,1.1) rotate3d(0,0,1,-3deg);transform:scale3d(1.1,1.1,1.1) rotate3d(0,0,1,-3deg)}100%{-webkit-transform:scale3d(1,1,1);transform:scale3d(1,1,1)}}\n\n.tada {-webkit-animation-name: tada;animation-name: tada;}\n', 0, 'a:0:{}', 0, ''),
(8, 0, 0, 'element-generator', 'Ð”Ð»Ñ Ð¾Ñ‚Ð¾Ð±Ñ€Ð°Ð¶ÐµÐ½Ð¸Ñ ÐºÐ°Ñ€Ñ‚Ð¸Ð½Ð¾Ðº Ð½ÑƒÐ¶ÐµÐ½ TV - element-img', 0, 1, 0, '<div class="gi-wrapper">\n[[!getResources?\n&parents=`[[*id]]`\n&tpl=`element-tpl`\n&sortby=`menuindex`\n&sortdir=`ASC`\n&limit=`999`\n&depth=`0`\n&includeTVs=`1`\n]]\n</div>\n</div>\n<script type="text/javascript">\nwindow.onload = function(){\n    /* Ñ€Ð°Ð²Ð½Ð°Ñ Ð²Ñ‹ÑÐ¾Ñ‚Ð° Ð±Ð»Ð¾ÐºÐ¾Ð² */\n    var giItemHeight = 0;\n    $(".gi-item").each(function(){\n        if(parseInt($(this).css("height")) > giItemHeight)\n        giItemHeight = parseInt($(this).css("height"));\n    });\n    $(".gi-item").css("height",giItemHeight);\n    /* Ð²ÐµÑ€Ñ‚Ð¸ÐºÐ°Ð»ÑŒÐ½Ð¾Ðµ Ñ†ÐµÐ½Ñ‚Ñ€Ð¾Ð²Ð°Ð½Ð¸Ðµ Ð½Ð°Ð·Ð²Ð°Ð½Ð¸Ñ */\n    var giNameHeight = 0;\n    $(".gi-name").each(function(){\n        if(parseInt($(this).css("height")) > giNameHeight){\n        giNameHeight = parseInt($(this).css("height"));}\n    });\n    $(".gi-name").each(function(){\n        console.log((parseInt(giNameHeight)-parseInt($(this).css("height")))/2 + "px");\n        if(parseInt($(this).css("height")) < parseInt(giNameHeight)){\n            console.log(giNameHeight);\n            $(this).css("padding-top", (parseInt(giNameHeight)-parseInt($(this).css("height")))/2 + "px");\n            $(this).css("padding-bottom", (parseInt(giNameHeight)-parseInt($(this).css("height")))/2 + "px");\n        }\n    });\n}\n</script>\n<!-- Ð³ÐµÐ½ÐµÑ€Ð°Ñ‚Ð¾Ñ€ ÑÐ»ÐµÐ¼ÐµÐ½Ñ‚Ð¾Ð² modx END -->', 0, 'a:0:{}', 0, ''),
(9, 0, 0, 'element-tpl', 'Ð”Ð»Ñ Ð¾Ñ‚Ð¾Ð±Ñ€Ð°Ð¶ÐµÐ½Ð¸Ñ ÐºÐ°Ñ€Ñ‚Ð¸Ð½Ð¾Ðº Ð½ÑƒÐ¶ÐµÐ½ TV - element-img', 0, 1, 0, '<div class=''gi-item''>\n	<a href="[[~[[+id]]]]" class="gi-image"><img src=''[[+tv.element-img:phpthumbof=`w=200&h=132&zc=1`]]'' alt="[[+menutitle:isnotempty=`[[+menutitle]]`:else=`[[+pagetitle]]`]]" /></a>\n	<a class="gi-name" href=''[[~[[+id]]]]''>[[+menutitle:isnotempty=`[[+menutitle]]`:else=`[[+pagetitle]]`]]</a>\n</div>', 0, 'a:0:{}', 0, ''),
(10, 0, 0, 'feed-back-form', 'Ð¤Ð¾Ñ€Ð¼Ð° Ð¾Ð±Ñ€Ð°Ñ‚Ð½Ð¾Ð¹ ÑÐ²ÑÐ·Ð¸', 0, 1, 0, '<!-- Ñ„Ð¾Ñ€Ð¼Ð° Ð¾Ð±Ñ€Ð°Ñ‚Ð½Ð¾Ð¹ ÑÐ²ÑÐ·Ð¸ -->\n<div id="fb-wrapper">\n	<h3 id="fb-header">ÐžÐ±Ñ€Ð°Ñ‚Ð½Ð°Ñ ÑÐ²ÑÐ·ÑŒ / Ð—Ð°ÐºÐ°Ð·Ð°Ñ‚ÑŒ Ð¾Ð±Ñ€Ð°Ñ‚Ð½Ñ‹Ð¹ Ð·Ð²Ð¾Ð½Ð¾Ðº</h3>\n	<table id="fb-form">\n		<tbody>\n			<tr>\n				<td style="width:35%;"><label for="inpname">Ð˜Ð¼Ñ<span style="color:red;">*</span>:</label></td>\n				<td><input type="text" name="name" class="fb-input" id="inpname" placeholder="Ð˜Ð¼Ñ"></td>\n			</tr>\n			<tr>\n				<td><label for="inptel">E-mail Ð¸Ð»Ð¸ Ð¢ÐµÐ»ÐµÑ„Ð¾Ð½ Ð´Ð»Ñ ÑÐ²ÑÐ·Ð¸<span style="color:red;">*</span>:</label></td>\n				<td><input type="text" name="tel" class="fb-input" id="inptel" placeholder="E-mail Ð¸Ð»Ð¸ Ð¢ÐµÐ»ÐµÑ„Ð¾Ð½ Ð´Ð»Ñ ÑÐ²ÑÐ·Ð¸"></td>\n			</tr>\n			<tr>\n				<td><label for="inpcomment">ÐšÐ¾Ð¼Ð¼ÐµÐ½Ñ‚Ð°Ñ€Ð¸Ð¹:</label></td>\n				<td><textarea name="comment" id="inpcomment" placeholder="ÐšÐ¾Ð¼Ð¼ÐµÐ½Ñ‚Ð°Ñ€Ð¸Ð¹"></textarea></td>\n			</tr>\n		</tbody>\n	</table>\n	<div id="fb-button-wr">\n		<div id="fb-ajaxgo">ÐžÑ‚Ð¿Ñ€Ð°Ð²Ð¸Ñ‚ÑŒ</div>\n			<div id="fb-successmsg"></div>\n	</div>\n</div>\n\n<script type="text/javascript">\n$(document).ready(function(){\n$(document.body).on("click", "#fb-ajaxgo", send);\n$(document.body).on("focus", ".fb-input", function(){$(this).css("border","1px solid #CCC");});\n    function send(){\n    var validate = true;\n    if ($("#fb-form").find("input[name=''name'']").val().length < 1){\n        $("#fb-form").find("input[name=''name'']").css("border","1px solid #D22");\n        validate = false;}\n    if ($("#fb-form").find("input[name=''tel'']").val().length < 1){\n        $("#fb-form").find("input[name=''tel'']").css("border","1px solid #D22");\n        validate = false;}\n    if (validate){\n    var need = "";\n    need += "<br>ÐšÐ¾Ð½Ñ‚Ð°ÐºÑ‚Ð½Ð°Ñ Ð¸Ð½Ñ„Ð¾Ñ€Ð¼Ð°Ñ†Ð¸Ñ: Ð˜Ð¼Ñ â€“ <b>" + $("#fb-form").find("input[name=''name'']").val() + "</b>;<br>Ð¢ÐµÐ»ÐµÑ„Ð¾Ð½ â€“ <b>" + $("#fb-form").find("input[name=''tel'']").val() + "</b>;";\n    if ($("#fb-form").find("textarea[name=''comment'']").val().length > 0){\n    need += "<br>ÐšÐ¾Ð¼Ð¼ÐµÐ½Ñ‚Ð°Ñ€Ð¸Ð¹ Ðº Ð·Ð°ÑÐ²ÐºÐµ: <b>" + $("#fb-form").find("textarea[name=''comment'']").val() + "</b>;";\n    }\noutput = JSON.stringify(need);\n\n$.ajax({\ntype: "POST",\ndata: {data1: output},\n  url:''js/mail.php'',\n  dataType:''json'',\n  success: function(){\n    $("#fb-ajaxgo").hide();\n    $("#fb-successmsg").html("Ð¡Ð¿Ð°ÑÐ¸Ð±Ð¾, Ð²Ð°ÑˆÐ° Ð·Ð°ÑÐ²ÐºÐ° Ð¿Ñ€Ð¸Ð½ÑÑ‚Ð°!");\n    $("#fb-successmsg").fadeIn(300).css("display","inline-block")/*.delay(7000).fadeOut(300)*/;\n},\nerror: function(){console.log("Ð¾ÑˆÐ¸Ð±ÐºÐ°");}\n});\n}\n}\n});\n</script>\n<!-- Ñ„Ð¾Ñ€Ð¼Ð° Ð¾Ð±Ñ€Ð°Ñ‚Ð½Ð¾Ð¹ ÑÐ²ÑÐ·Ð¸ END -->', 0, 'a:0:{}', 0, ''),
