INSERT INTO `modx_site_snippets` (`id`, `source`, `property_preprocess`, `name`, `description`, `editor_type`, `category`, `cache_type`, `snippet`, `locked`, `properties`, `moduleguid`, `static`, `static_file`) VALUES
(7, 1, 0, 'pdoResources', '', 0, 5, 0, '/* @var array $scriptProperties */\nif (isset($parents) && $parents === '''') {\n	$scriptProperties[''parents''] = $modx->resource->id;\n}\nif (!empty($returnIds)) {\n	$scriptProperties[''return''] = ''ids'';\n}\n\n// Adding extra parameters into special place so we can put them in results\n/** @var modSnippet $snippet */\n$additionalPlaceholders = array();\nif ($snippet = $modx->getObject(''modSnippet'', array(''name'' => ''pdoResources''))) {\n	$properties = unserialize($snippet->properties);\n	foreach ($scriptProperties as $k => $v) {\n		if (!isset($properties[$k])) {\n			$additionalPlaceholders[$k] = $v;\n		}\n	}\n}\n$scriptProperties[''additionalPlaceholders''] = $additionalPlaceholders;\n\n/* @var pdoFetch $pdoFetch */\n$fqn = $modx->getOption(''pdoFetch.class'', null, ''pdotools.pdofetch'', true);\nif ($pdoClass = $modx->loadClass($fqn, '''', false, true)) {\n	$pdoFetch = new $pdoClass($modx, $scriptProperties);\n}\nelseif ($pdoClass = $modx->loadClass($fqn, MODX_CORE_PATH . ''components/pdotools/model/'', false, true)) {\n	$pdoFetch = new $pdoClass($modx, $scriptProperties);\n}\nelse {\n	$modx->log(modX::LOG_LEVEL_ERROR, ''Could not load pdoFetch from "MODX_CORE_PATH/components/pdotools/model/".'');\n	return false;\n}\n$pdoFetch->addTime(''pdoTools loaded'');\n$output = $pdoFetch->run();\n\n$log = '''';\nif ($modx->user->hasSessionContext(''mgr'') && !empty($showLog)) {\n	$log .= ''<pre class="pdoResourcesLog">'' . print_r($pdoFetch->getTime(), 1) . ''</pre>'';\n}\n\n// Return output\nif (!empty($returnIds)) {\n	$modx->setPlaceholder(''pdoResources.log'', $log);\n	if (!empty($toPlaceholder)) {\n		$modx->setPlaceholder($toPlaceholder, $output);\n	}\n	else {\n		return $output;\n	}\n}\nelseif (!empty($toSeparatePlaceholders)) {\n	$output[''log''] = $log;\n	$modx->setPlaceholders($output, $toSeparatePlaceholders);\n}\nelse {\n	$output .= $log;\n\n	if (!empty($tplWrapper) && (!empty($wrapIfEmpty) || !empty($output))) {\n		$output = $pdoFetch->getChunk($tplWrapper, array(''output'' => $output), $pdoFetch->config[''fastMode'']);\n	}\n\n	if (!empty($toPlaceholder)) {\n		$modx->setPlaceholder($toPlaceholder, $output);\n	}\n	else {\n		return $output;\n	}\n}', 0, 'a:44:{s:3:"tpl";a:7:{s:4:"name";s:3:"tpl";s:4:"desc";s:17:"pdotools_prop_tpl";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:0:"";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:9:"returnIds";a:7:{s:4:"name";s:9:"returnIds";s:4:"desc";s:23:"pdotools_prop_returnIds";s:4:"type";s:13:"combo-boolean";s:7:"options";a:0:{}s:5:"value";b:0;s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:7:"showLog";a:7:{s:4:"name";s:7:"showLog";s:4:"desc";s:21:"pdotools_prop_showLog";s:4:"type";s:13:"combo-boolean";s:7:"options";a:0:{}s:5:"value";b:0;s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:8:"fastMode";a:7:{s:4:"name";s:8:"fastMode";s:4:"desc";s:22:"pdotools_prop_fastMode";s:4:"type";s:13:"combo-boolean";s:7:"options";a:0:{}s:5:"value";b:0;s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:6:"sortby";a:7:{s:4:"name";s:6:"sortby";s:4:"desc";s:20:"pdotools_prop_sortby";s:4:"type";s:9:"textfield";s:7:"options";a:0:{}s:5:"value";s:11:"publishedon";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:7:"sortdir";a:7:{s:4:"name";s:7:"sortdir";s:4:"desc";s:21:"pdotools_prop_sortdir";s:4:"type";s:4:"list";s:7:"options";a:2:{i:0;a:2:{s:4:"text";s:3:"ASC";s:5:"value";s:3:"ASC";}i:1;a:2:{s:4:"text";s:4:"DESC";s:5:"value";s:4:"DESC";}}s:5:"value";s:4:"DESC";s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:5:"limit";a:7:{s:4:"name";s:5:"limit";s:4:"desc";s:19:"pdotools_prop_limit";s:4:"type";s:11:"numberfield";s:7:"options";a:0:{}s:5:"value";i:10;s:7:"lexicon";s:19:"pdotools:properties";s:4:"area";s:0:"";}s:6:"offset";a:7:{s:4:"name";s:6:"offset";s:4:"desc";s:20:"pdotools_prop_offset";s:4:"type";s:11:"numberfield";s:7:"options";a:0:{}s:5:"value";i:0;s:7:"lexicon";s:19:"pdo