(15, 0, 0, 'phpthumbof', 'A custom output filter that generates thumbnails securely with phpThumb.', 0, 0, 0, '/**\n * phpThumbOf\n *\n * Copyright 2009-2012 by Shaun McCormick <shaun@modx.com>\n *\n * phpThumbOf is free software; you can redistribute it and/or modify it\n * under the terms of the GNU General Public License as published by the Free\n * Software Foundation; either version 2 of the License, or (at your option) any\n * later version.\n *\n * phpThumbOf is distributed in the hope that it will be useful, but WITHOUT ANY\n * WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS FOR\n * A PARTICULAR PURPOSE. See the GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License along with\n * phpThumbOf; if not, write to the Free Software Foundation, Inc., 59 Temple\n * Place, Suite 330, Boston, MA 02111-1307 USA\n *\n * @package phpthumbof\n */\n/**\n * A custom output filter for phpThumb\n *\n * @var modX $modx\n * @var array $scriptProperties\n * @var phpThumbOf $phpThumbOf\n * @var string $input\n * @var string|array $options\n *\n * @package phpthumbof\n */\nif (empty($modx)) return '''';\nif (!$modx->loadClass(''modPhpThumb'',$modx->getOption(''core_path'').''model/phpthumb/'',true,true)) {\n    $modx->log(modX::LOG_LEVEL_ERROR,''[phpThumbOf] Could not load modPhpThumb class.'');\n    return '''';\n}\nif (empty($input)) {\n    $modx->log(modX::LOG_LEVEL_DEBUG,''[phpThumbOf] Empty image path passed, aborting.'');\n    return '''';\n}\n$modelPath = $modx->getOption(''phpthumbof.core_path'',null,$modx->getOption(''core_path'').''components/phpthumbof/'').''model/'';\nrequire_once $modelPath.''phpthumbof/phpthumbof.class.php'';\n$phpThumbOf = new phpThumbOf($modx,$scriptProperties);\n\n$phpThumbOf->getCacheDirectory();\n$phpThumbOf->ensureCacheDirectoryIsWritable();\n\n$thumbnail = $phpThumbOf->createThumbnailObject();\n$thumbnail->setInput($input);\n$thumbnail->setOptions($options);\n$thumbnail->initializeService();\nreturn $thumbnail->render();', 0, NULL, '', 0, ''),
(16, 0, 0, 'rezimgcrop', '', 0, 6, 0, '/**\n * RezImgCrop\n * Copyright 2011 by Artdevue.com  <info@artdevue.com>\n * Arguings at a forum http://community.modx-cms.ru/\n * @package rezimgcrop\n */\n/**\n * RezImgCrop\n * A dynamic form processing Snippet for MODx Revolution 2.0.\n *\n * @package rezimgcrop\n */\n\n$output = trim($input);\n$serve = $modx->getOption(''base_path'');\n$opt = explode('','',$options);\nif (count($opt) >= 1) {\n  $trans = array("-"=>"", "x"=>"", ","=>"");\n  $m_name = strip_tags(strtr($options, $trans));\n  $images_name = basename($output);\n  $images_dir = dirname($output);\n  $imagprev = $images_dir{0} == ''/'' ? '''' : ''/'';\n  $images_dir = $imagprev.$images_dir;\n  $dir_new = $images_dir.''/rezcrop/''; \n  if (!file_exists($serve.$dir_new.$m_name.''_''.$images_name)) {    \n    if(!file_exists($serve.$dir_new)) mkdir($serve.$dir_new, 0777);\n    $newimg = $dir_new.$m_name.''_''.$images_name;\n    if (!copy($serve.$imagprev.$output, $serve.$newimg)) {\n      return $output;\n}\n    $col = count($opt)-1;\n    for ($x=0; $x<=$col;){\n      $frc = explode(''-'',$opt[$x]);\n      $par = explode(''x'',$frc[1]);\n      if($frc[0] == ''r'') {\n        if(!$par[1]){\n            list($w, $h) = getimagesize($serve.$newimg);\n            if ($w < $h) {\n                $parnol = $par[0];\n                $par[0] = '''';\n                $par[1] = $parnol;\n            }\n        }\n	$modx->runSnippet(''RezImg'',array(\n   ''file_input'' => $serve.$newimg,\n	  ''file_output'' => $serve.$newimg,\n	  ''w_o'' => $par[0],\n	  ''h_o'' => $par[1]\n));\n      }\n      if($frc[0] == ''c'') {\n	list($w, $h) = getimagesize($serve.$newimg);\n    		$ym = $xm = 0;\n    		$ym = ($h - $par[1])/2;\n            $xm = ($w - $par[0])/2;\n	$modx->runSnippet(''CropImg'',array(\n   ''file_input'' => $serve.$newimg,\n	  ''file_output'' => $serve.$newimg,\n	  ''crop'' => array($xm,$ym,$par[0]+$xm,$par[1]+$ym)\n));\n      }\n      if($frc[0] == ''g'') {	\n	$modx->runSnippet(''GrayscaleImg'',array(\n   ''file_input'' => $serve.$newimg,\n	  ''file_output'' => $serve.$newimg\n));\n}\n      if ($frc[0] == ''min'') {\n        list($w, $h) = getimagesize($serve.$newimg);\n        if($w < $h){\n            $maxwo = $frc[1];\n            $maxho = '''';\n        }else{\n            $maxwo = '''';\n            $maxho = $frc[1];\n        }\n        $modx->runSnippet(''RezImg'',array(\n   ''file_input'' => $serve.$newimg,\n	  ''file_output'' => $serve.$newimg,\n	  ''w_o'' => $maxwo,\n	  ''h_o'' => $maxho\n));\n      }\n      $x++;\n    }\n  }\n  $output = $dir_new.$m_name.''_''.$images_name;\n  return $output;\n}\nreturn $output;', 0, 'a:0:{}', '', 0, ''),
(17, 0, 0, 'RezImg', '', 0, 6, 0, '/**\n * RezImgCrop\n * Copyright 2011 by Artdevue.com  <info@artdevue.com>\n * Arguings at a forum http://community.modx-cms.ru/\n * @package rezimgcrop\n */\n/**\n * RezImgCrop\n * A dynamic form processing Snippet for MODx Revolution 2.0.\n *\n * @package rezimgcrop\n */\n$percent = false;\nlist($w_i, $h_i, $type) = getimagesize($file_input);\n  if (!$w_i || !$h_i) {\n    return $file_input;\n    }\n    $types = array('''',''gif'',''jpeg'',''png'');\n    $ext = $types[$type];\n    if ($ext) {\n      $func = ''imagecreatefrom''.$ext;\n      $img = $func($file_input);\n    } else {\n    return $file_input;\n    }\n  if ($percent) {\n    $w_o *= $w_i / 100;\n    $h_o *= $h_i / 100;\n  }\n  if (!$h_o) $h_o = $w_o/($w_i/$h_i);\n  if (!$w_o) $w_o = $h_o/($h_i/$w_i);\n  $img_o = imagecreatetruecolor($w_o, $h_o);\n  if ($type == 3) {\n  imagesavealpha($img_o, true);\n  $trans_colour = imagecolorallocatealpha($img_o, 255, 255, 255, 127);\n  imagefill($img_o, 0, 0, $trans_colour);\n  }\n  imagecopyresampled($img_o, $img, 0, 0, 0, 0, $w_o, $h_o, $w_i, $h_i);\n  if ($type == 2) {\n    imagejpeg($img_o,$file_output,100);\n    imagedestroy($img_o);\n  } else {\n    $func = ''image''.$ext;\n    return $func($img_o,$file_output);\n  }', 0, 'a:0:{}', '', 0, ''),
(18, 0, 0, 'CropImg', '', 0, 6, 0, '/**\n * RezImgCrop\n * Copyright 2011 by Artdevue.com  <info@artdevue.com>\n * Arguings at a forum http://community.modx-cms.ru/\n * @package rezimgcrop\n */\n/**\n * RezImgCrop\n * A dynamic form processing Snippet for MODx Revolution 2.0.\n *\n * @package rezimgcrop\n */\n$percent = false;\nlist($w_i, $h_i, $type) = getimagesize($file_input);\n  if (!$w_i || !$h_i) {\n    return $file_input;\n    }\n    $types = array('''',''gif'',''jpeg'',''png'');\n    $ext = $types[$type];\n    if ($ext) {\n      $func = ''imagecreatefrom''.$ext;\n      $img = $func($file_input);\n    } else {\n      return $file_input;\n    }\n  if ($crop == ''square'') {\n    if ($w_i > $h_i) {\n      $x_o = ($w_i - $h_i) / 2;\n      $min = $h_i;\n    } else {\n      $y_o = ($h_i - $w_i) / 2;\n      $min = $w_i;\n    }\n    $w_o = $h_o = $min;\n  } else {\n    list($x_o, $y_o, $w_o, $h_o) = $crop;\n    if ($percent) {\n      $w_o *= $w_i / 100;\n      $h_o *= $h_i / 100;\n      $x_o *= $w_i / 100;\n      $y_o *= $h_i / 100;\n    }\n      if ($w_o < 0) $w_o += $w_i;\n      $w_o -= $x_o;\n       if ($h_o < 0) $h_o += $h_i;\n    $h_o -= $y_o;\n  }\n  $img_o = imagecreatetruecolor($w_o, $h_o);\n  imagecopy($img_o, $img, 0, 0, $x_o, $y_o, $w_o, $h_o);\n  if ($type == 2) {\n    imagejpeg($img_o,$file_output,100);\n    imagedestroy($img_o);\n  } else {\n    $func = ''image''.$ext;\n    return $func($img_o,$file_output);\n  }', 0, 'a:0:{}', '', 0, ''),
(19, 0, 0, 'GrayscaleImg', 'Let''s transform color images to a shade of gray', 0, 6, 0, '//ÐŸÐ¾Ð»ÑƒÑ‡Ð°ÐµÐ¼ Ñ€Ð°Ð·Ð¼ÐµÑ€Ñ‹ Ð¸Ð·Ð¾Ð±Ñ€Ð°Ð¶ÐµÐ½Ð¸Ñ\n  $img_size = GetImageSize($file_input);\n  $width = $img_size[0];\n  $height = $img_size[1];\n  //Ð¡Ð¾Ð·Ð´Ð°ÐµÐ¼ Ð½Ð¾Ð²Ð¾Ðµ Ð¸Ð·Ð¾Ð±Ñ€Ð°Ð¶ÐµÐ½Ð¸Ðµ Ñ Ñ‚Ð°ÐºÐ¼Ð¸Ð¼Ð¸ Ð¶Ðµ Ñ€Ð°Ð·Ð¼ÐµÑ€Ð°Ð¼Ð¸\n  $img = imageCreate($width,$height);\n  //Ð—Ð°Ð´Ð°ÐµÐ¼ Ð½Ð¾Ð²Ð¾Ð¼Ñƒ Ð¸Ð·Ð¾Ð±Ñ€Ð°Ð¶ÐµÐ½Ð¸ÑŽ Ð¿Ð°Ð»Ð¸Ñ‚Ñ€Ñƒ "Ð¾Ñ‚Ñ‚ÐµÐ½ÐºÐ¸ ÑÐµÑ€Ð¾Ð³Ð¾" (grayscale)\n  for ($c = 0; $c < 256; $c++) {\n    ImageColorAllocate($img, $c,$c,$c);\n  }\n  //Ð¡Ð¾Ð´Ð°ÐµÐ¼ Ð¸Ð·Ð¾Ð±Ñ€Ð°Ð¶ÐµÐ½Ð¸Ðµ Ð¸Ð· Ñ„Ð°Ð¹Ð»Ð° Jpeg\n  $img2 = ImageCreateFromJpeg($file_input);\n  //ÐžÐ±ÑŠÐµÐ´Ð¸Ð½ÑÐµÐ¼ Ð´Ð²Ð° Ð¸Ð·Ð¾Ð±Ñ€Ð°Ð¶ÐµÐ½Ð¸Ñ\n  ImageCopyMerge($img,$img2,0,0,0,0, $width, $height, 100);\n  //Ð¡Ð¾Ñ…Ñ€Ð°Ð½ÑÐµÐ¼ Ð¿Ð¾Ð»ÑƒÑ‡ÐµÐ½Ð½Ð¾Ðµ Ð¸Ð·Ð¾Ð±Ñ€Ð°Ð¶ÐµÐ½Ð¸Ðµ\n  imagejpeg($img, $file_output);\n //ÐžÑÐ²Ð¾Ð±Ð¾Ð¶Ð´Ð°ÐµÐ¼ Ð¿Ð°Ð¼ÑÑ‚ÑŒ, Ð·Ð°Ð½ÑÑ‚ÑƒÑŽ Ð¸Ð·Ð¾Ð±Ñ€Ð°Ð¶ÐµÐ½Ð¸ÐµÐ¼\n  imagedestroy($img);', 0, 'a:0:{}', '', 0, ''),
(20, 0, 0, 'Wayfinder', 'Wayfinder for MODx Revolution 2.0.0-beta-5 and later.', 0, 0, 0, '/**\n * Wayfinder Snippet to build site navigation menus\n *\n * Totally refactored from original DropMenu nav builder to make it easier to\n * create custom navigation by using chunks as output templates. By using\n * templates, many of the paramaters are no longer needed for flexible output\n * including tables, unordered- or ordered-lists (ULs or OLs), definition lists\n * (DLs) or in any other format you desire.\n *\n * @version 2.1.1-beta5\n * @author Garry Nutting (collabpad.com)\n * @author Kyle Jaebker (muddydogpaws.com)\n * @author Ryan Thrash (modx.com)\n * @author Shaun McCormick (modx.com)\n * @author Jason Coward (modx.com)\n *\n * @example [[Wayfinder? &startId=`0`]]\n *\n * @var modX $modx\n * @var array $scriptProperties\n * \n * @package wayfinder\n */\n$wayfinder_base = $modx->getOption(''wayfinder.core_path'',$scriptProperties,$modx->getOption(''core_path'').''components/wayfinder/'');\n\n/* include a custom config file if specified */\nif (isset($scriptProperties[''config''])) {\n    $scriptProperties[''config''] = str_replace(''../'','''',$scriptProperties[''config'']);\n    $scriptProperties[''config''] = $wayfinder_base.''configs/''.$scriptProperties[''config''].''.config.php'';\n} else {\n    $scriptProperties[''config''] = $wayfinder_base.''configs/default.config.php'';\n}\nif (file_exists($scriptProperties[''config''])) {\n    include $scriptProperties[''config''];\n}\n\n/* include wayfinder class */\ninclude_once $wayfinder_base.''wayfinder.class.php'';\nif (!$modx->loadClass(''Wayfinder'',$wayfinder_base,true,true)) {\n    return ''error: Wayfinder class not found'';\n}\n$wf = new Wayfinder($modx,$scriptProperties);\n\n/* get user class definitions\n * TODO: eventually move these into config parameters */\n$wf->_css = array(\n    ''first'' => isset($firstClass) ? $firstClass : '''',\n    ''last'' => isset($lastClass) ? $lastClass : ''last'',\n    ''here'' => isset($hereClass) ? $hereClass : ''active'',\n    ''parent'' => isset($parentClass) ? $parentClass : '''',\n    ''row'' => isset($rowClass) ? $rowClass : '''',\n    ''outer'' => isset($outerClass) ? $outerClass : '''',\n    ''inner'' => isset($innerClass) ? $innerClass : '''',\n    ''level'' => isset($levelClass) ? $levelClass: '''',\n    ''self'' => isset($selfClass) ? $selfClass : '''',\n    ''weblink'' => isset($webLinkClass) ? $webLinkClass : ''''\n);\n\n/* get user templates\n * TODO: eventually move these into config parameters */\n$wf->_templates = array(\n    ''outerTpl'' => isset($outerTpl) ? $outerTpl : '''',\n    ''rowTpl'' => isset($rowTpl) ? $rowTpl : '''',\n    ''parentRowTpl'' => isset($parentRowTpl) ? $parentRowTpl : '''',\n    ''parentRowHereTpl'' => isset($parentRowHereTpl) ? $parentRowHereTpl : '''',\n    ''hereTpl'' => isset($hereTpl) ? $hereTpl : '''',\n    ''innerTpl'' => isset($innerTpl) ? $innerTpl : '''',\n    ''innerRowTpl'' => isset($innerRowTpl) ? $innerRowTpl : '''',\n    ''innerHereTpl'' => isset($innerHereTpl) ? $innerHereTpl : '''',\n    ''activeParentRowTpl'' => isset($activeParentRowTpl) ? $activeParentRowTpl : '''',\n    ''categoryFoldersTpl'' => isset($categoryFoldersTpl) ? $categoryFoldersTpl : '''',\n    ''startItemTpl'' => isset($startItemTpl) ? $startItemTpl : ''''\n);\n\n/* process Wayfinder */\n$output = $wf->run();\nif ($wf->_config[''debug'']) {\n    $output .= $wf->renderDebugOutput();\n}\n\n/* output results */\nif ($wf->_config[''ph'']) {\n    $modx->setPlaceholder($wf->_config[''ph''],$output);\n} else {\n    return $output;\n}', 0, 'a:48:{s:5:"level";a:6:{s:4:"name";s:5:"level";s:4:"desc";s:25:"prop_wayfinder.level_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:1:"0";s:7:"lexicon";s:20:"wayfinder:properties";}s:11:"includeDocs";a:6:{s:4:"name";s:11:"includeDocs";s:4:"desc";s:31:"prop_wayfinder.includeDocs_desc";s:4:"type";s:9:"textfield";s:7:"options";s:0:"";s:5:"value";s:1:"0";s:7:"lexi