INSERT INTO `modx_site_templates` (`id`, `source`, `property_preprocess`, `templatename`, `description`, `editor_type`, `category`, `icon`, `template_type`, `content`, `locked`, `properties`, `static`, `static_file`) VALUES
(1, 0, 0, 'Ð‘Ð°Ð·Ð¾Ð²Ñ‹Ð¹ ÑˆÐ°Ð±Ð»Ð¾Ð½', 'Template', 0, 0, '', 0, '<!DOCTYPE html>\n<html>\n<head>\n	<meta charset="utf-8"/>\n	<title>[[*pagetitle]] â€“ [[++site_name]]</title>\n	<link rel="shortcut icon" type="image/x-icon" href="css/images/favicon.ico" />\n	<link rel="stylesheet" href="css/style.css" type="text/css" />\n	[[$bxslider-css]]\n	\n	<script src="js/jquery-1.11.1.min.js" type="text/javascript"></script>\n	<!--[if lt IE 9]>\n		<script src="js/modernizr.custom.js"></script>\n	<![endif]-->\n	[[$bxslider-js]]\n	<!--<script src="js/functions.js" type="text/javascript"></script>-->\n</head>\n<body>\n	<!-- wrapper -->\n	<div id="wrapper">\n		<!-- shell -->\n		<div class="shell">\n			<!-- container -->\n			<div class="container">\n							\n				<!-- header -->\n				<header class="header">\n					<div id="logo"><a href="[[~1]]">Ð Ð¾ÑÐ¢Ñ€ÐµÐ¹Ð´</a></div>\n					<nav id="navigation">\n						<ul>\n							<li class="[[*id:is=1:then=`active`]] first"><a href="[[~1]]">Ð“Ð»Ð°Ð²Ð½Ð°Ñ</a></li>\n							<li [[*id:is=5:then=`class="active"`]]><a href="[[~5]]">Ðž ÐºÐ¾Ð¼Ð¿Ð°Ð½Ð¸Ð¸</a></li>\n							<li [[*id:is=19:then=`class="active"`]]><a href="[[~19]]">ÐŸÐ¾ÑÑ‚Ð°Ð²Ñ‰Ð¸ÐºÐ°Ð¼</a></li>\n							<li [[*id:is=9:then=`class="active"`]]><a href="[[~9]]">ÐšÐ»Ð¸ÐµÐ½Ñ‚Ð°Ð¼</a></li>\n							<li [[*id:is=20:then=`class="active"`]]><a href="[[~20]]">Ð Ð°Ð±Ð¾Ñ‚Ð° Ñƒ Ð½Ð°Ñ</a></li>\n							<li class="[[*id:is=4:then=`active`]] last"><a href="[[~4]]">ÐšÐ¾Ð½Ñ‚Ð°ÐºÑ‚Ñ‹</a></li>\n						</ul>\n					</nav>\n					<div class="cl">&nbsp;</div>\n				</header>\n				<!-- end of header -->\n				<div class="main">\n					<!-- slider -->\n                    [[*id:is=`1`:then=`<div class="slider-wrapper"><ul class="bxslider">\n<li><img src="/img/slide1.jpg" alt="slide1" title=""/></li>\n<li><img src="/img/slide2.jpg" alt="slide2" title=""/></li>\n<li><img src="/img/slide3.jpg" alt="slide3" title=""/></li>\n<li><img src="/img/slide4.jpg" alt="slide4" title=""/></li>\n</ul>\n<script>\n$(document).ready(function(){\n  $(''.bxslider'').bxSlider({mode:''fade'',captions:false,pager:true,controls:false});\n});\n</script></div>`]]\n					<!-- end of slider -->\n					<!-- cols -->\n					<section class="cols">\n						[[*id:is=`1`:then=`<div class="col50">\n							<!-- <h3>ÐŸÑ€Ð¸Ð²ÐµÑ‚ÑÑ‚Ð²Ð¸Ðµ</h3> -->\n							[[*content]]\n						</div>\n\n						<div class="col50">\n							<h3>ÐÐ¾Ð²Ð¾ÑÑ‚Ð¸</h3>\n							[[$news-generator-onindex]]\n							<p class="center"><a href="[[~14]]" class="col-btn">Ð’ÑÐµ Ð½Ð¾Ð²Ð¾ÑÑ‚Ð¸</a></p>\n						</div>`:else=`<div class="col100">\n<div>\n    <div class="about-left-side">\n    [[*id:is=`5`:then=`\n        <ul>\n            <li><a href="#" data-about-goto="1" class="active">Ðž ÐšÐ¾Ð¼Ð¿Ð°Ð½Ð¸Ð¸</a></li>\n            <li><a href="#" data-about-goto="2">Ð”ÐµÑÑ‚ÐµÐ»ÑŒÐ½Ð¾ÑÑ‚ÑŒ</a></li>\n            <li><a href="#" data-about-goto="3">ÐŸÑ€Ð¸ÐµÐ¼ÑƒÑ‰ÐµÑÑ‚Ð²Ð°</a></li>\n        </ul>\n    `]]\n    [[*id:is=`9`:then=`\n        <ul>\n            <li><a href="[[~9]]" class="active">Ð”Ð¸ÑÑ‚Ñ€Ð¸Ð±ÑƒÑ†Ð¸Ñ</a></li>\n            <li><a href="[[~12]]">ÐŸÑ€Ð¾Ð¸Ð·Ð²Ð¾Ð´ÑÑ‚Ð²Ð¾</a></li>\n        </ul>\n    `]]\n    [[*id:is=`12`:then=`\n        <ul>\n            <li><a href="[[~9]]">Ð”Ð¸ÑÑ‚Ñ€Ð¸Ð±ÑƒÑ†Ð¸Ñ</a></li>\n            <li><a href="[[~12]]" class="active">ÐŸÑ€Ð¾Ð¸Ð·Ð²Ð¾Ð´ÑÑ‚Ð²Ð¾</a></li>\n        </ul>\n    `]]\n    </div>\n    <div class="about-right-side">\n    [[*id:isnot=`5`:then=`<h1>[[*pagetitle]]</h1>`]]\n	[[*content]]\n    </div>\n</div>\n							<div style="clear:both"></div>\n						</div>`]]\n						<div class="cl">&nbsp;</div>\n					</section>\n					<!-- end of cols  -->\n\n[[*id:is=`5`:then=`\n<script>\n    $(".about-left-side").find("a").on("click", function(){\n        console.log(1);\n        $(".about-right-side").find(".about-id").removeClass("active");\n        var t = $(this);\n        t.parent().siblings("li").find("a").removeClass("active");\n        t.addClass("active");\n        var d = t.data("about-goto");\n        var i = $(".about-right-side").find("[data-about-id=''"+d+"'']");\n        i.addClass("active");\n        return false;\n    });\n</script>\n`]]\n					<!-- box -->\n\n						[[*id:isnot=`4`:and:isnot=`20`:then=`\n					<section class="box">\n						<span class="shadow-t"></span>\n    						[[*id:isnot=`9`:and:isnot=`12`:then=`<h3>ÐÐ°ÑˆÐ¸ ÐºÐ»Ð¸ÐµÐ½Ñ‚Ñ‹</h3>`:else=`\n    						    [[*id:is=`9`:then=`<h3>ÐÐ°ÑˆÐ¸ Ð¿Ð¾ÑÑ‚Ð°Ð²Ñ‰Ð¸ÐºÐ¸</h3>`]]\n    						    [[*id:is=`12`:then=`<h3>ÐÐ°ÑˆÐ° Ð¿Ñ€Ð¾Ð´ÑƒÐºÑ†Ð¸Ñ</h3>`]]`]]\n						<div class="cl">&nbsp;</div>\n						<!-- entries -->\n						<div class="entries">\n						`]]\n						\n\n						[[*id:isnot=`4`:and:isnot=`20`:then=`\n    						[[*id:isnot=`9`:and:isnot=`12`:then=`[[$klienti-carusel]]`:else=`\n    						    [[*id:is=`9`:then=`[[$suppliers-carusel]]`]]\n    						    [[*id:is=`12`:then=`[[$snaks-carusel]]`]]`]]\n\n                        <div class="cl">&nbsp;</div>\n                        <span class="shadow-b"></span>\n						</div>\n						`]]\n					<!-- end of entries -->\n					</section>\n					<!-- end of box -->\n					\n					<!-- services -->\n					\n					<section class="services">\n						<div class="widget contact-widget">\n							<h3>ÐšÐ¾Ð½Ñ‚Ð°ÐºÑ‚Ð½Ð°Ñ Ð¸Ð½Ñ„Ð¾Ñ€Ð¼Ð°Ñ†Ð¸Ñ</h3>\n							<ul>\n								<li><strong>ÐÐ´Ñ€ÐµÑ:</strong> 197342, Ð Ð¾ÑÑÐ¸Ñ, Ð¡Ð°Ð½ÐºÑ‚-ÐŸÐµÑ‚ÐµÑ€Ð±ÑƒÑ€Ð³, Ð¿Ñ€. ÐžÐ±ÑƒÑ…Ð¾Ð²ÑÐºÐ¾Ð¹ ÐžÐ±Ð¾Ñ€Ð¾Ð½Ñ‹ Ð´.7</li>\n								<li><strong>Ð¢ÐµÐ».:</strong> +7(812)412-34-22</li>\n								<li><strong>Ð¤Ð°ÐºÑ:</strong> +7(812)438-31-83</li>\n								<li><strong>Email:</strong> <a href="mailto:info@rtspb.com">info@rtspb.com</a></li>\n							</ul>\n						</div>\n						<div class="widget socials-widget">\n							<h3>ÐœÑ‹ Ð² ÑÐ¾Ñ†. ÑÐµÑ‚ÑÑ…</h3>\n							[[$soc-seti]]\n						</div>\n						<div class="cl">&nbsp;</div>\n					</section>\n					<!-- end of services -->\n\n				</div>\n				<!-- end of main -->\n			</div>\n			<!-- end of container -->\n			<div class="footer">\n				<nav class="footer-nav">\n					<ul>\n						<li><a href="[[~1]]">Ð“Ð»Ð°Ð²Ð½Ð°Ñ</a></li>\n						<li><a href="[[~5]]">Ðž ÐºÐ¾Ð¼Ð¿Ð°Ð½Ð¸Ð¸</a></li>\n						<li><a href="[[~19]]">ÐŸÐ¾ÑÑ‚Ð°Ð²Ñ‰Ð¸ÐºÐ°Ð¼</a></li>\n						<li><a href="[[~9]]">ÐšÐ»Ð¸ÐµÐ½Ñ‚Ð°Ð¼</a></li>\n						<li><a href="[[~20]]">Ð Ð°Ð±Ð¾Ñ‚Ð° Ñƒ Ð½Ð°Ñ</a></li>\n						<li><a href="[[~4]]">ÐšÐ¾Ð½Ñ‚Ð°ÐºÑ‚Ñ‹</a></li>\n					</ul>\n				</nav>\n				<p class="copy">Ð¡Ð¾Ð·Ð´Ð°Ð½Ð¸Ðµ ÑÐ°Ð¹Ñ‚Ð° â€“ <a href="http://go-up.info/sozdanie-saitov.html" target="_blank" >GoUp.info</a></p>\n			</div>\n		</div>\n		<!-- end of shell -->\n	</div>\n	<!-- end of wrappert -->\n</body>\n</html>', 0, 'a:0:{}', 0, '');
